INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-001', 'Vintage 90s Adidas Track Jacket — Navy & Grey', 'JACKETS', '₹1,399', 1399, 'Rare vintage 90s Adidas track jacket in two-tone navy and silver-grey colorblocking with iconic three-stripe accents across the collar, chest, and sleeves. Features embroidered classic Adidas logo and full-zip front. Pristine condition. Authentic Pre-owned Jacket.', '["images/zf001-1.jpg","images/zf001-2.jpg","images/zf001-3.jpg","images/zf001-4.jpg"]', '["XL"]', 'XL', '52"', '29"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.875Z', '2026-09-08T17:54:39.875Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-002', 'Vintage Lacoste Sport Striped Track Jacket — White', 'JACKETS', '₹1,499', 1499, 'Vintage Lacoste Sport full-zip track jacket in crisp white with subtle black horizontal pinstripes. Features signature embroidered green crocodile on the chest, embroidered Lacoste lettering on the back collar, branded zipper hardware, zippered hand pockets, and adjustable hem drawcord. Authentic Pre-owned Jacket.', '["images/zf002-1.jpg","images/zf002-2.jpg","images/zf002-3.jpg","images/zf002-4.jpg","images/zf002-5.jpg","images/zf002-6.jpg","images/zf002-7.jpg","images/zf002-8.jpg","images/zf002-9.jpg","images/zf002-10.jpg"]', '["XL"]', 'XL', '48"', '29"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-003', 'Vintage Adidas Trefoil Track Jacket — Black & White', 'JACKETS', '₹1,399', 1399, 'Iconic vintage Adidas Trefoil track jacket in timeless black with contrast white three-stripe trim along the sleeves. Features embroidered white Trefoil logo on the chest, branded Adidas zipper hardware, zippered hand pockets, and elasticated hem. Authentic Pre-owned Jacket.', '["images/zf003-1.jpg","images/zf003-2.jpg","images/zf003-3.jpg","images/zf003-4.jpg","images/zf003-5.jpg"]', '["L"]', 'L', '50"', '27.5"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-004', 'Vintage Fila Biella Italia Track Jacket — Midnight Navy', 'JACKETS', '₹1,299', 1299, 'Vintage Fila Biella Italia lightweight track jacket in deep midnight navy. Features embroidered FILA logo on the chest, embroidered F-box emblem on the back shoulder, custom enamel F-logo zipper hardware, structured collar, and elasticated cuffs & hem. Authentic Pre-owned Jacket.', '["images/zf004-1.jpg","images/zf004-2.jpg","images/zf004-3.jpg","images/zf004-4.jpg","images/zf004-5.jpg","images/zf004-6.jpg","images/zf004-7.jpg"]', '["L"]', 'L', '48"', '27"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-005', 'Official NFL Seattle Seahawks Track Jacket — Navy & Neon Green', 'JACKETS', '₹1,199', 1199, 'Official NFL Seattle Seahawks performance track jacket in deep navy with vibrant Action Green side panels and contrast flatlock stitching. Features premium embroidered Seahawks logo on the chest, neon full front zip, and soft warm fleece lining. Pristine 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf005-4.jpg","images/zf005-2.jpg","images/zf005-1.jpg","images/zf005-3.jpg","images/zf005-5.jpg"]', '["L"]', 'L', '49"', '28"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-006', 'Vintage 90s Adidas Arc Track Jacket — Navy & Silver', 'JACKETS', '₹1,499', 1499, 'Rare vintage 90s Adidas track jacket in deep navy with dynamic curved silver-grey chest and sleeve paneling. Features embroidered classic Adidas logo on the chest, custom rubberized pocket zipper pulls, full zip front, and vintage country flags collar tag. Excellent 9/10 condition. Authentic Pre-owned Jacket.', '["images/zf006-1.jpg","images/zf006-2.jpg","images/zf006-3.jpg","images/zf006-4.jpg","images/zf006-5.jpg","images/zf006-6.jpg","images/zf006-7.jpg"]', '["L"]', 'L', '48"', '30"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-007', 'Vintage Adidas "Pleasant Valley Vikings" Track Jacket — Navy', 'JACKETS', '₹1,299', 1299, 'Vintage Adidas collegiate track jacket in midnight navy with bold white three-stripe sleeve panels. Features custom turquoise "Pleasant Valley Vikings Basketball" embroidery, embroidered Adidas chest logo, full front zip, breathable white mesh lining, and side pockets. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf007-3.jpg","images/zf007-2.jpg","images/zf007-5.jpg","images/zf007-4.jpg","images/zf007-1.jpg"]', '["M"]', 'M', '44"', '27"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-008', 'Vintage 80s/90s Adidas Trefoil Colorblock Track Jacket — Magenta & Teal', 'JACKETS', '₹1,299', 1299, 'Statement vintage 80s/90s Adidas Trefoil shell track jacket in iconic magenta purple, vibrant teal green, and royal blue geometric colorblocking. Features embroidered teal Trefoil chest logo, turquoise three stripes across shoulders and sleeve cuffs, custom engraved Trefoil metal zipper pull, and high funnel neck. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf008-1.jpg","images/zf008-2.jpg","images/zf008-3.jpg","images/zf008-4.jpg","images/zf008-5.jpg","images/zf008-6.jpg","images/zf008-7.jpg","images/zf008-8.jpg"]', '["L"]', 'L', '50"', '28"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-009', 'Vintage 90s Reebok Vector Track Jacket — Electric Cyan', 'JACKETS', '₹1,299', 1299, 'Vibrant vintage 90s Reebok shell track jacket in bright electric cyan blue. Features tonal embroidered Reebok Vector logo on the chest, vintage blue-banner collar tag, contrast white zipper hardware on side pockets, adjustable hem drawcord, and breathable back ventilation yoke. Authentic Pre-owned Jacket.', '["images/zf009-1.jpg","images/zf009-2.jpg","images/zf009-3.jpg","images/zf009-4.jpg","images/zf009-5.jpg"]', '["L"]', 'L', '48"', '28"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.876Z', '2026-09-08T17:54:39.876Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-010', 'Vintage 80s/90s Adidas Trefoil Track Jacket — Navy, Lavender & Emerald', 'JACKETS', '₹1,299', 1299, 'Rare vintage 80s/90s Adidas Trefoil track jacket featuring geometric colorblocking in midnight navy, soft lavender, emerald green, and crisp white. Features embroidered Trefoil chest logo, ribbed lavender collar, custom Trefoil metal zip pull, emerald three-stripe shoulder accents, and geometric back chevron paneling. Authentic Pre-owned Jacket.', '["images/zf010-1.jpg","images/zf010-2.jpg","images/zf010-3.jpg","images/zf010-4.jpg","images/zf010-5.jpg"]', '["XL"]', 'XL', '52"', '28"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-011', 'Vintage Adidas Performance Track Jacket — Red & Black', 'JACKETS', '₹999', 999, 'Vintage Adidas Performance shell jacket in scarlet red with black colorblock panels and white three-stripe trim. Features packable hood inside high collar, full red mesh lining, reflective contour piping, Adidas logo zipper pulls, storm flap closure, and zippered hand pockets. Authentic Pre-owned Jacket.', '["images/zf011-1.jpg","images/zf011-2.jpg","images/zf011-3.jpg","images/zf011-4.jpg","images/zf011-5.jpg","images/zf011-6.jpg","images/zf011-7.jpg","images/zf011-8.jpg","images/zf011-9.jpg","images/zf011-10.jpg","images/zf011-11.jpg"]', '["S"]', 'S', '40"', '22"', '8/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-012', 'Vintage JAKO Sport Performance Track Jacket — Navy & Royal Blue', 'JACKETS', '₹1,199', 1199, 'Technical vintage JAKO sport track jacket in navy blue, royal blue, and white with dynamic curved colorblocking and "Panos" sponsor graphic. Features perforated breathable mesh side and underarm ventilation panels, embroidered JAKO chest emblem, custom rubberized zipper pulls, and adjustable interior hem drawcord. Excellent 9/10 condition. Authentic Pre-owned Jacket.', '["images/zf012-1.jpg","images/zf012-2.jpg","images/zf012-3.jpg","images/zf012-4.jpg","images/zf012-5.jpg","images/zf012-6.jpg","images/zf012-7.jpg","images/zf012-8.jpg","images/zf012-9.jpg","images/zf012-10.jpg","images/zf012-11.jpg","images/zf012-12.jpg"]', '["M","L"]', 'M/L', '44"', '26"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-013', 'Vintage K2 Technical Outdoor Shell Jacket — Hot Pink & Fuchsia', 'JACKETS', '₹1,199', 1199, 'High-performance vintage K2 Technical Outdoor shell jacket in vibrant hot pink and deep fuchsia colorblocking. Features weatherproof shell, high storm collar with packable hood zip, reflective vertical pocket accents, velcro cuff adjusters, breathable mesh interior lining, and K2 jacquard satin hem lining. Authentic Pre-owned Jacket.', '["images/zf013-1.jpg","images/zf013-2.jpg","images/zf013-3.jpg","images/zf013-4.jpg","images/zf013-5.jpg","images/zf013-6.jpg","images/zf013-7.jpg","images/zf013-8.jpg","images/zf013-9.jpg","images/zf013-10.jpg","images/zf013-11.jpg","images/zf013-12.jpg","images/zf013-13.jpg"]', '["S","M"]', 'S/M', '40"', '25"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-014', 'Vintage 90s Adidas Trefoil Track Jacket — Midnight Navy & White', 'JACKETS', '₹1,299', 1299, 'Iconic vintage 90s Adidas Trefoil track jacket in midnight navy with crisp white three-stripe shoulder and sleeve trim. Features embroidered white Trefoil chest logo, custom molded white Trefoil zipper pull, high stand collar with concealed packable hood zip, and contrast white zippered pockets. Authentic Pre-owned Jacket.', '["images/zf014-1.jpg","images/zf014-2.jpg","images/zf014-3.jpg","images/zf014-4.jpg","images/zf014-5.jpg","images/zf014-6.jpg","images/zf014-7.jpg"]', '["L"]', 'L', '50"', '28"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-015', 'Vintage Y2K Eckō Unltd. 3D Geometric Camo Bomber Jacket — Grey', 'JACKETS', '₹1,199', 1199, 'Vintage Y2K Eckō Unltd. bomber track jacket in a striking monochrome 3D isometric geometric cube camo pattern. Features bold embroidered "ECKŌ UNLTD." chest appliqué, custom metal Rhino medallion zipper pull, chunky zipper, ribbed knit collar, cuffs, and hem with red contrast inner piping. Authentic Pre-owned Jacket.', '["images/zf015-1.jpg","images/zf015-2.jpg","images/zf015-3.jpg","images/zf015-4.jpg","images/zf015-5.jpg","images/zf015-6.jpg","images/zf015-7.jpg"]', '["XL"]', 'XL', '54"', '29"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-016', 'Vintage 80s/90s ASICS Colorblock Half-Zip Anorak — Neon Pink & Black', 'JACKETS', '₹1,199', 1199, 'Rare vintage 80s/90s ASICS half-zip pullover anorak windbreaker in bold black, neon hot pink, and white colorblocking. Features centered front kangaroo cargo flap pocket with ASICS graphic embroidery, neon pink zipper, large circular ASICS medallion back graphic, and elasticated cuffs & hem. Authentic Pre-owned Jacket.', '["images/zf016-1.jpg","images/zf016-2.jpg","images/zf016-3.jpg","images/zf016-4.jpg","images/zf016-5.jpg","images/zf016-6.jpg","images/zf016-7.jpg","images/zf016-8.jpg"]', '["XL"]', 'XL', '54"', '29"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-017', 'Vintage 90s Champion Duke Blue Devils Pullover Windbreaker — Royal Blue', 'JACKETS', '₹1,199', 1199, 'Vintage 90s Champion Duke Blue Devils NCAA pullover shooting windbreaker in royal blue. Features stitched tackle twill arched "DUKE" chest lettering, striped rib-knit V-neck collar & cuffs, embroidered Blue Devil mascot sleeve patch, embroidered Champion back logo, side pockets, and adjustable waist cinch toggle. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf017-1.jpg","images/zf017-2.jpg","images/zf017-3.jpg","images/zf017-4.jpg","images/zf017-5.jpg","images/zf017-6.jpg","images/zf017-7.jpg"]', '["XL"]', 'XL', '50"', '27"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
