INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-019', 'Vintage ASICS Firenze Marathon Track Jacket — Royal Blue, Red & White', 'JACKETS', '₹999', 999, 'Vintage ASICS Firenze Marathon running track jacket in royal blue with red and white colorblock accents. Features embroidered ASICS chest logo, Firenze Marathon chest & sleeve graphics, silver reflective piping, large ASICS back logo, zippered side pockets, and breathable interior mesh lining. Authentic Pre-owned Jacket.', '["images/zf019-1.jpg","images/zf019-2.jpg","images/zf019-3.jpg","images/zf019-4.jpg","images/zf019-5.jpg","images/zf019-6.jpg","images/zf019-7.jpg","images/zf019-8.jpg"]', '["M"]', 'M', '44"', '27"', '8/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-020', 'Vintage New Balance Outdoor Shell Track Jacket — Black & Red', 'JACKETS', '₹1,299', 1299, 'Vintage New Balance outdoor shell track jacket in black with bold red shoulder/sleeve paneling and white piping accents. Features embroidered New Balance chest logo, fleece-lined red collar, snap-button storm flap closure, velcro cuff adjusters, and breathable interior mesh lining. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf020-1.jpg","images/zf020-2.jpg","images/zf020-3.jpg","images/zf020-4.jpg","images/zf020-5.jpg","images/zf020-6.jpg","images/zf020-7.jpg"]', '["S"]', 'S', '42"', '20.5"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-021', 'Vintage The North Face HyVent 2.5L Hooded Shell Jacket — Magenta', 'JACKETS', '₹1,199', 1199, 'Vintage The North Face technical HyVent 2.5L outdoor shell rain jacket in vibrant magenta pink. Features silver embroidered TNF chest and back logos, HyVent 2.5L sleeve branding, underarm pit zip vents, attached cinch hood, mesh stow pocket with branded tab, and adjustable bottom hem bungee toggle. Excellent 9/10 condition. Authentic Pre-owned Jacket.', '["images/zf021-1.jpg","images/zf021-2.jpg","images/zf021-3.jpg","images/zf021-4.jpg","images/zf021-5.jpg","images/zf021-6.jpg","images/zf021-7.jpg"]', '["M"]', 'M', '44"', '24"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-022', 'Vintage 90s Nike Swoosh Track Jacket — Midnight Navy & White', 'JACKETS', '₹1,299', 1299, 'Vintage 90s Nike Swoosh athletic track jacket in midnight navy with white and grey stripe sleeve paneling. Features embroidered white Nike Swoosh chest emblem, chunky front zipper with custom rubberized Swoosh pull tab, waffle-knit inner collar lining, zippered hand pockets, and adjustable hem drawcord. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf022-1.jpg","images/zf022-2.jpg","images/zf022-3.jpg","images/zf022-4.jpg","images/zf022-5.jpg","images/zf022-6.jpg","images/zf022-7.jpg","images/zf022-8.jpg"]', '["XL"]', 'XL', '52"', '30"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-023', 'Vintage Champion "St. Francis Xavier College" Track Jacket — Navy & Red', 'JACKETS', '₹1,199', 1199, 'Vintage Champion Teamwear collegiate track jacket in midnight navy with scarlet red side and sleeve paneling accented by white piping. Features embroidered St. Francis Xavier College chest crest emblem, bright red stand collar, full front zip, and elasticated cuffs. Excellent 9/10 condition. Authentic Pre-owned Jacket.', '["images/zf023-1.jpg","images/zf023-2.jpg","images/zf023-3.jpg","images/zf023-4.jpg","images/zf023-5.jpg"]', '["S"]', 'S', '40"', '25"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-024', 'Vintage Kappa Technical Track Jacket — Black, Cyan & White', 'JACKETS', '₹999', 999, 'Vintage Kappa technical shell track jacket in black with electric cyan accents and white side paneling featuring a halftone polka-dot gradient mesh print. Features embroidered cyan Kappa Omini chest emblem, Aero-Plus technology, branded zipper pull, breathable cyan mesh inner lining, and adjustable bottom hem bungee toggle. Authentic Pre-owned Jacket.', '["images/zf024-1.jpg","images/zf024-2.jpg","images/zf024-3.jpg","images/zf024-4.jpg","images/zf024-5.jpg","images/zf024-6.jpg","images/zf024-7.jpg"]', '["L"]', 'L', '44"', '27.5"', '8/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-025', 'Vintage Kappa "Moto Corse" Racing Track Jacket — White, Black & Pink', 'JACKETS', '₹1,299', 1299, 'Vintage Kappa Moto Corse motorsport track jacket in crisp white with contrast black side/sleeve paneling and vibrant pink racing accents. Features stitched Kappa Moto Corse chest shield badge, embroidered Kappa Omini logo, sleeve number ''67'' patches, custom metal zipper pull, and black/white striped ribbed collar & hem. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf025-1.jpg","images/zf025-2.jpg","images/zf025-3.jpg","images/zf025-4.jpg","images/zf025-5.jpg"]', '["XS"]', 'XS', '37"', '22"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-026', 'Vintage FILA Colorblock Hooded Anorak Jacket — Soft Pink & Charcoal', 'JACKETS', '₹1,299', 1299, 'Vintage FILA colorblock half-zip hooded anorak jacket in pastel soft pink, white, and charcoal black. Features embroidered FILA logo on centered kangaroo flap pocket, bold screen-printed FILA logo across the back, round custom F-box metal zipper pull, cinch drawstring hood, breathable interior mesh lining, and adjustable bottom hem toggle. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf026-1.jpg","images/zf026-2.jpg","images/zf026-3.jpg","images/zf026-4.jpg","images/zf026-5.jpg"]', '["S"]', 'S', '43"', '26"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-027', 'Vintage Adidas Trefoil Asymmetric Colorblock Track Jacket — White, Teal & Magenta', 'JACKETS', '₹1,399', 1399, 'Vintage Adidas Trefoil ''Asymm Track Jkt'' in crisp white with asymmetric teal green, magenta pink, and black colorblock paneling. Features classic black 3-stripes down sleeves, embroidered black Trefoil chest logo, custom embossed Trefoil zipper pull, cotton-blend interior lining, and adjustable bottom hem drawstring cinch cord. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf027-1.jpg","images/zf027-2.jpg","images/zf027-3.jpg","images/zf027-4.jpg","images/zf027-5.jpg"]', '["M"]', 'M', '48"', '27.5"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-028', 'Vintage Nike Swoosh Minimalist Track Jacket — Midnight Navy', 'JACKETS', '₹1,199', 1199, 'Vintage Nike minimalist athletic track jacket in deep midnight navy with a clean white horizontal chest piping stripe. Features embroidered white Nike Swoosh emblem on left chest, silver metallic zipper pull with debossed Swoosh logo, high stand-up collar, breathable mesh interior lining, zippered side pockets, and elasticated hem. Flawless 10/10 condition. Authentic Pre-owned Jacket.', '["images/zf028-1.jpg","images/zf028-2.jpg","images/zf028-3.jpg","images/zf028-4.jpg","images/zf028-5.jpg"]', '["L"]', 'L', '44"', '27.5"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZF-029', 'Vintage Nike Court Tennis Track Jacket — Midnight Navy & White', 'JACKETS', '₹1,199', 1199, 'Vintage Nike Court performance tennis track jacket in deep midnight navy with a crisp white chest stripe. Features embroidered white Nike Swoosh on left chest, Nike Court tennis tab on lower hem, Nike FIT DRY technology, full front zip, breathable mesh lining, and adjustable bottom hem bungee toggle. Excellent 9/10 condition. Authentic Pre-owned Jacket.', '["images/zf029-1.jpg","images/zf029-2.jpg","images/zf029-3.jpg","images/zf029-4.jpg","images/zf029-5.jpg","images/zf029-6.jpg"]', '["XL"]', 'XL', '46"', '28"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-001', 'Vintage GAP Arch Logo Pullover Hoodie — Midnight Navy', 'HOODIES', '₹999', 999, 'Classic vintage GAP pullover hoodie in deep midnight navy. Features the iconic felted GAP arch logo appliqué across the chest, kangaroo front pocket, drawstring hood, and ribbed cuffs & hem. A timeless American staple in excellent vintage condition. Authentic Pre-owned Hoodie.', '["images/h1-1.jpg","images/h1-2.jpg","images/h1-3.jpg","images/h1-4.jpg","images/h1-5.jpg","images/h1-6.jpg"]', '["M","L"]', 'M/L', '44"', '27"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-002', 'Vintage Dickies Colorblock Pullover Hoodie — Red & Heather Grey', 'HOODIES', '₹1,299', 1299, 'Vintage Dickies workwear pullover hoodie in bold red with contrast heather grey hood. Features embroidered Dickies script logo on the chest, woven Dickies label at the hem, kangaroo front pocket, and ribbed cuffs & hem. Solid vintage character. Authentic Pre-owned Hoodie.', '["images/h2-1.jpg","images/h2-2.jpg","images/h2-3.jpg","images/h2-4.jpg","images/h2-5.jpg","images/h2-6.jpg"]', '["M","L"]', 'M/L', '42"', '25"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-003', 'Vintage Nike Script Pullover Hoodie — Deep Plum', 'HOODIES', '₹999', 999, 'Vintage Nike pullover hoodie in rich deep plum purple. Features tonal embroidered Nike script logo on the chest, drawstring hood, kangaroo front pocket, and ribbed cuffs & hem. A rare colourway with a moody, premium aesthetic. Authentic Pre-owned Hoodie.', '["images/h3-1.jpg","images/h3-2.jpg","images/h3-3.jpg","images/h3-4.jpg","images/h3-5.jpg","images/h3-6.jpg"]', '["M","L"]', 'M/L', '42"', '26.5"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-004', 'Vintage Superdry Tokyo Track & Field Raglan Hoodie — Grey & Navy', 'HOODIES', '₹1,199', 1199, 'Vintage Superdry Tokyo raglan pullover hoodie in charcoal grey body with contrast midnight navy sleeves. Features bold stitched "Tokyo Superdry Dept 72 Track & Field" chest appliqué, embroidered number 2 on the left sleeve, custom Superdry drawstring tags, kangaroo pocket, and ribbed cuffs & hem. Excellent vintage condition. Authentic Pre-owned Hoodie.', '["images/h4-1.jpg","images/h4-2.jpg","images/h4-3.jpg","images/h4-4.jpg","images/h4-5.jpg","images/h4-6.jpg","images/h4-7.jpg","images/h4-8.jpg"]', '["M","L"]', 'M/L', '42"', '27.5"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-005', 'Vintage NBA Store ''Fifth Ave'' Washed Zip-Up Hoodie — Washed Grey', 'HOODIES', '₹1,299', 1299, 'Vintage NBA Store Fifth Avenue New York zip-up hoodie in acid-washed slate grey. Features screen-printed NBA Store ''Fifth Ave, New York'' gothic lettering with NBA logo on the chest, full front zip, drawstring hood, kangaroo patch pockets, and ribbed cuffs & hem. Heavy character from genuine wear. Authentic Pre-owned Hoodie.', '["images/h5-1.jpg","images/h5-2.jpg","images/h5-3.jpg","images/h5-4.jpg","images/h5-5.jpg","images/h5-6.jpg"]', '["L"]', 'L', '46"', '26"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-006', 'Vintage Superdry Tokyo Script Pullover Hoodie — Faded Navy', 'HOODIES', '₹1,299', 1299, 'Vintage Superdry Tokyo pullover hoodie in faded navy blue. Features large embroidered red & white Tokyo SuperDry script logo with Japanese kanji detail on the chest, branded woven Superdry drawstring tips, kangaroo front pocket, ribbed cuffs & hem, and a red Superdry tab on the left cuff. Excellent vintage condition. Authentic Pre-owned Hoodie.', '["images/h6-1.jpg","images/h6-2.jpg","images/h6-3.jpg","images/h6-4.jpg","images/h6-5.jpg","images/h6-6.jpg","images/h6-7.jpg","images/h6-8.jpg"]', '["L"]', 'L', '46"', '28"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-007', 'Official MLB Majestic LA Dodgers Cooperstown Collection Hoodie — Royal Blue', 'HOODIES', '₹1,299', 1299, 'Official MLB Majestic LA Dodgers Cooperstown Collection pullover hoodie in vibrant electric royal blue. Features bold embroidered ''Dodgers Baseball Club'' chest graphic with Majestic and MLB logo patches, embroidered LA logo on the hood, ribbed cuffs & hem, and kangaroo front pocket. A statement vintage sports hoodie. Authentic Pre-owned Hoodie.', '["images/h7-1.jpg","images/h7-2.jpg","images/h7-3.jpg","images/h7-4.jpg","images/h7-5.jpg","images/h7-6.jpg"]', '["L"]', 'L', '45"', '28"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-008', 'Vintage Dickies 1922 Pullover Hoodie — Sage Green', 'HOODIES', '₹1,199', 1199, 'Vintage Dickies 1922 pullover hoodie in washed sage green. Features embroidered ''Dickies 1922'' chest logo in tonal white, contrast white flatlock stitching throughout, branded Dickies drawstring tips, woven Dickies patch at the hem, kangaroo front pocket, and ribbed cuffs & hem. 100% cotton. Flawless 10/10 condition. Authentic Pre-owned Hoodie.', '["images/h8-1.jpg","images/h8-2.jpg","images/h8-3.jpg","images/h8-4.jpg","images/h8-5.jpg","images/h8-6.jpg","images/h8-7.jpg","images/h8-8.jpg"]', '["M","L"]', 'M/L', '42"', '25"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-009', 'Vintage GAP Arch Logo Zip-Up Hoodie — Heather Grey', 'HOODIES', '₹1,299', 1299, 'Vintage GAP full zip-up hoodie in washed heather grey. Features the iconic felted GAP arch logo appliqué across the chest in navy, full front YKK metal zipper, drawstring hood, kangaroo hand pockets, and ribbed cuffs & hem. Classic American staple with authentic vintage wear. Authentic Pre-owned Hoodie.', '["images/h9-1.jpg","images/h9-2.jpg","images/h9-3.jpg","images/h9-4.jpg","images/h9-5.jpg"]', '["M","L"]', 'M/L', '42"', '25"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-010', 'Vintage GAP Arch Logo Zip-Up Hoodie — Royal Blue & Gold', 'HOODIES', '₹1,299', 1299, 'Vintage GAP full zip-up hoodie in vibrant royal blue. Features the bold felted GAP arch logo appliqué across the chest in gold and white, full front zipper, drawstring hood, kangaroo hand pockets, and ribbed cuffs & hem. A rare and eye-catching colourway in excellent vintage condition. Authentic Pre-owned Hoodie.', '["images/h10-1.jpg","images/h10-2.jpg","images/h10-3.jpg","images/h10-4.jpg","images/h10-5.jpg"]', '["XL"]', 'XL', '54"', '29"', '9/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-011', 'Vintage Nautica Arch Logo Quarter-Zip Sweatshirt — Black', 'HOODIES', '₹1,299', 1299, 'Vintage Nautica quarter-zip pullover sweatshirt in deep black. Features large embroidered navy and white arched ''NAUTICA'' collegiate logo across the chest, high ribbed stand collar with quarter-zip closure, woven Nautica hem tag, and ribbed cuffs & hem. Bold preppy aesthetic with a premium nautical feel. Authentic Pre-owned Sweatshirt.', '["images/h11-1.jpg","images/h11-2.jpg","images/h11-3.jpg","images/h11-4.jpg","images/h11-5.jpg","images/h11-6.jpg","images/h11-7.jpg"]', '["M","L"]', 'M/L', '44"', '26.5"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-012', 'Vintage Champion Script Pullover Hoodie — Heather Grey', 'HOODIES', '₹1,299', 1299, 'Vintage Champion Reverse Weave-era pullover hoodie in classic heather grey. Features bold embroidered navy and red Champion script logo across the chest, embroidered Champion ''C'' logo on the left cuff, woven ''Authentic American Athletic Apparel — Rochester, USA'' label at the hem, kangaroo front pocket, and ribbed cuffs & hem. A true vintage Champion grail. Authentic Pre-owned Hoodie.', '["images/h12-1.jpg","images/h12-2.jpg","images/h12-3.jpg","images/h12-4.jpg","images/h12-5.jpg","images/h12-6.jpg"]', '["L"]', 'L', '46"', '25.5"', '10/10', 'SOLD_OUT', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-013', 'Y2K Graphic Zip-Up Hoodie — ''Devil Script'' Black', 'HOODIES', '₹1,199', 1199, 'Y2K-era full zip-up hoodie in jet black. Features a bold puff-print gothic bubble letter graphic with devil horns, pink star accents, and a devil tail motif across the chest — a statement streetwear piece straight from the early 2000s. Full front zipper, drawstring hood, kangaroo pockets, and ribbed cuffs & hem. Authentic Pre-owned Hoodie.', '["images/h13-1.jpg","images/h13-2.jpg","images/h13-3.jpg","images/h13-4.jpg"]', '["L"]', 'L', '46"', '26"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-014', 'Disney Stella Lou Bunny Ear Pullover Hoodie — Baby Pink', 'HOODIES', '₹1,199', 1199, 'Official Disney Stella Lou character pullover hoodie in soft baby pink. Features 3D bunny ear detail on the hood with mint green inner lining, embroidered Stella Lou character graphic on the left chest with cursive ''StellaLou'' script, branded drawstring tips, kangaroo front pocket, and ribbed cuffs & hem. A rare and adorable collector''s piece. Authentic Pre-owned Hoodie.', '["images/h14-1.jpg","images/h14-2.jpg","images/h14-3.jpg","images/h14-4.jpg"]', '["L"]', 'L', '45"', '26.5"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-015', 'Barbapapa Cartoon Graphic Pullover Hoodie — Cream White', 'HOODIES', '₹999', 999, 'Vintage Barbapapa cartoon pullover hoodie in off-white cream. Features a charming printed graphic of the Barbapapa family in a pink bathtub on the left chest, white drawstring hood, kangaroo front pocket, and ribbed cuffs & hem. A fun, nostalgic collector''s piece for fans of classic European animation. Authentic Pre-owned Hoodie.', '["images/h15-2.jpg","images/h15-1.jpg","images/h15-3.jpg","images/h15-4.jpg","images/h15-5.jpg"]', '["M","L"]', 'M/L', '44"', '25.5"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-016', 'Tribal Gear 1989 Demon Horn Ninja Balaclava Hoodie — Jet Black', 'HOODIES', '₹1,299', 1299, 'Ultra-rare vintage Tribal Gear 1989 ninja balaclava hoodie in jet black. Features 3D demon horn hood with built-in balaclava face mask eyeholes, heavyweight puff embroidered Tribal 1989 graffiti chest appliqué with red contrast border stitching, thumbhole cuff cutouts, kangaroo front pocket, and woven Tribal hem tag. Authentic Pre-owned Hoodie.', '["images/h16-1.jpg","images/h16-2.jpg","images/h16-3.jpg","images/h16-4.jpg","images/h16-5.jpg","images/h16-6.jpg","images/h16-7.jpg"]', '["L","XL"]', 'L/XL', '46"', '26.5"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-017', 'Vintage Oakley Big Logo Contrast Hood Pullover Hoodie — Black & Burgundy', 'HOODIES', '₹1,299', 1299, 'Vintage Oakley pullover hoodie in faded jet black with contrast burgundy wine inner hood lining. Features iconic white Oakley stretch logo screenprinted across the chest, drawstring hood, kangaroo front pocket, and ribbed cuffs & hem. A classic piece of Y2K techwear heritage. Authentic Pre-owned Hoodie.', '["images/h17-1.jpg","images/h17-2.jpg","images/h17-3.jpg","images/h17-4.jpg"]', '["L"]', 'L', '44"', '26"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, sale_source, sold_at, created_at, updated_at) VALUES ('ZH-018', 'Nike Air Jordan Jumpman Zip-Up Hoodie — Black & Red', 'HOODIES', '₹1,299', 1299, 'Vintage Nike Air Jordan full zip-up fleece hoodie in faded black. Features embroidered red Jumpman logo on the chest, custom embossed metal Air Jordan zipper pull, contrast thick red drawstrings, front split kangaroo pockets, and ribbed cuffs & hem. Authentic Pre-owned Hoodie.', '["images/h18-1.jpg","images/h18-2.jpg","images/h18-3.jpg","images/h18-4.jpg","images/h18-5.jpg","images/h18-6.jpg","images/h18-7.jpg"]', '["L"]', 'L', '44"', '27"', '9/10', 'SOLD_OUT', 'INSTAGRAM_DM', '2026-09-10T06:12:44.000Z', '2026-09-08T17:54:39.877Z', '2026-09-10T06:12:44.000Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-019', 'Vintage Stüssy Big Back Logo Pullover Hoodie — Slate Navy', 'HOODIES', '₹1,199', 1199, 'Classic vintage Stüssy pullover hoodie in washed slate navy blue. Features crisp embroidered white Stüssy script logo on the left chest, oversized iconic Stüssy script graphic printed across the back, drawstring hood, kangaroo front pocket, and ribbed cuffs & hem. Authentic Pre-owned Hoodie.', '["images/h19-1.jpg","images/h19-2.jpg","images/h19-3.jpg","images/h19-4.jpg","images/h19-5.jpg"]', '["XL"]', 'XL', '48"', '29.5"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, sale_source, sold_at, created_at, updated_at) VALUES ('ZH-020', 'Vintage Adidas Originals Trefoil Colorblock Anorak Hoodie — Red, Blue & White', 'HOODIES', '₹1,099', 1099, 'Vintage Adidas Originals quarter-zip anorak hoodie in vibrant 90s colorblocking of scarlet red, royal blue, and optic white. Features large rubberized white Adidas Trefoil chest logo, quarter-zip front with drawcord hood, side hand pockets, and ribbed hem & cuffs. Authentic Pre-owned Hoodie.', '["images/h20-1.jpg","images/h20-2.jpg","images/h20-3.jpg","images/h20-4.jpg"]', '["L","XL"]', 'L/XL', '46"', '27"', '9/10', 'SOLD_OUT', 'INSTAGRAM_DM', '2026-09-10T06:12:44.000Z', '2026-09-08T17:54:39.877Z', '2026-09-10T06:12:44.000Z');
