INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-022', 'Moda NI Tech Quarter-Zip Fleece Hoodie — Heather Grey', 'HOODIES', '₹1,099', 1099, 'Technical streetwear quarter-zip hoodie in classic heather grey. Features statement branded ''MODA NI'' nylon zipper ribbon pull, rubberized ''BEST CLASSIC'' chest badge, contrast black drawstrings with metal aglets, kangaroo front pocket, and ribbed hem & cuffs. Authentic Pre-owned Hoodie.', '["images/h22-1.jpg","images/h22-2.jpg","images/h22-3.jpg","images/h22-4.jpg","images/h22-5.jpg"]', '["M"]', 'M', '42"', '24.5"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-023', 'New York Popular ''Houston'' Varsity Raglan Zip-Up Hoodie — Heather Grey & Black', 'HOODIES', '₹1,199', 1199, 'Vintage collegiate raglan zip-up hoodie in heather grey with contrast black sleeves. Features bold arched ''HOUSTON'' felt appliqué lettering across the chest, full front zip, split kangaroo pockets, and varsity striped ribbed cuffs & hem. Authentic Pre-owned Hoodie.', '["images/h23-1.jpg","images/h23-2.jpg","images/h23-3.jpg","images/h23-4.jpg"]', '["L"]', 'L', '46"', '26"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-024', 'Vintage GAP Arch Logo Pullover Hoodie — Crimson Red', 'HOODIES', '₹1,299', 1299, 'Classic vintage GAP pullover hoodie in rich crimson red. Features the iconic navy & white felted GAP arch logo appliqué across the chest, drawstring hood, kangaroo front pocket, and ribbed cuffs & hem. A timeless American vintage essential. Authentic Pre-owned Hoodie.', '["images/h24-1.jpg","images/h24-2.jpg","images/h24-3.jpg","images/h24-4.jpg","images/h24-5.jpg"]', '["L","XL"]', 'L/XL', '50"', '27"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-025', 'Adidas Originals Layered Sleeve Graphic Pullover Hoodie — Crisp White', 'HOODIES', '₹1,299', 1299, 'Adidas Originals double-layer sleeve pullover hoodie in crisp optic white. Features embroidered blue Trefoil logo on the chest, layered short-over-long sleeves with retro Adidas heritage graphics, peace sign hand graphic, drawstring hood, and kangaroo front pocket. Authentic Pre-owned Hoodie.', '["images/h25-1.jpg","images/h25-2.jpg","images/h25-3.jpg","images/h25-4.jpg","images/h25-5.jpg","images/h25-6.jpg","images/h25-7.jpg","images/h25-8.jpg","images/h25-9.jpg","images/h25-10.jpg"]', '["L"]', 'L', '44"', '24.5"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, sale_source, sold_at, created_at, updated_at) VALUES ('ZH-026', 'Vintage Nike Mini Embroidered Swoosh Pullover Hoodie — Mineral Teal', 'HOODIES', '₹1,199', 1199, 'Vintage Nike minimalist pullover hoodie in washed mineral teal. Features mini embroidered white Nike Swoosh on the left chest, contrast white drawstrings, kangaroo front pocket, and ribbed cuffs & hem. A clean, everyday streetwear piece. Authentic Pre-owned Hoodie.', '["images/h26-1.jpg","images/h26-2.jpg","images/h26-3.jpg","images/h26-4.jpg"]', '["L","XL"]', 'L/XL', '48"', '25"', '9/10', 'SOLD_OUT', 'INSTAGRAM_DM', '2026-09-10T11:53:14.000Z', '2026-09-08T17:54:39.877Z', '2026-09-10T11:53:14.000Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-027', 'Vintage Fila ''Stile Sportivo'' Side-Tape Pullover Hoodie — Off White', 'HOODIES', '₹1,199', 1199, 'Vintage Fila ''Stile Sportivo Italiano'' pullover hoodie in off-white. Features continuous Fila jacquard logo tape running across the hood and down both sleeves, embroidered F-box chest patch, crossover hood neckline, kangaroo front pocket, and ribbed hem. Authentic Pre-owned Hoodie.', '["images/h27-1.jpg","images/h27-2.jpg","images/h27-3.jpg","images/h27-4.jpg","images/h27-5.jpg","images/h27-6.jpg","images/h27-7.jpg"]', '["L"]', 'L', '44"', '24.5"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, sale_source, sold_at, created_at, updated_at) VALUES ('ZH-028', 'Harajuku Celestial White Tiger Embroidered Layered Hoodie — Pastel Pink', 'HOODIES', '₹1,399', 1399, 'Harajuku oriental aesthetic layered pullover hoodie in soft pastel pink. Features an intricate embroidered celestial white tiger and golden crescent moon chest motif, layered cream contrast sleeves with embroidered lantern graphics, braided tasseled drawstrings, and gathered elastic hem. Authentic Pre-owned Hoodie.', '["images/h28-1.jpg","images/h28-2.jpg","images/h28-3.jpg","images/h28-4.jpg","images/h28-5.jpg","images/h28-6.jpg"]', '["M"]', 'M', '43"', '22"', '10/10', 'SOLD_OUT', 'INSTAGRAM_DM', '2026-09-09T16:26:45.000Z', '2026-09-08T17:54:39.877Z', '2026-09-09T16:26:45.000Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-029', 'Fubon Braves Basketball Collegiate Pullover Hoodie — Navy Blue', 'HOODIES', '₹1,099', 1099, 'Official Fubon Braves Basketball collegiate pullover hoodie in deep navy blue. Features large arched ''BRAVES'' felt appliqué across the chest, contrast turquoise and teal arm stripes, woven locker patch at the kangaroo pocket, embroidered star on the left cuff, and ribbed hem & cuffs. Authentic Pre-owned Hoodie.', '["images/h29-1.jpg","images/h29-2.jpg","images/h29-3.jpg","images/h29-4.jpg","images/h29-5.jpg","images/h29-6.jpg","images/h29-7.jpg","images/h29-8.jpg","images/h29-9.jpg","images/h29-10.jpg","images/h29-11.jpg"]', '["M"]', 'M', '42"', '24"', '9/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
INSERT OR REPLACE INTO products (id, product_name, category, price, numeric_price, description, images, sizes, display_size, chest, length, condition, status, created_at, updated_at) VALUES ('ZH-030', 'O!Oi Studio Korea Signature Logo Pullover Hoodie — Cream Beige', 'HOODIES', '₹1,099', 1099, 'O!Oi Studio Korea streetwear pullover hoodie in warm cream beige. Features embroidered baby blue O!Oi chenille letter applique and stitched ''©COPYRIGHT SINCE 1990 oi studio co., Ltd.'' text across the chest, drawstring hood, kangaroo front pocket, and ribbed hem & cuffs. Authentic Pre-owned Hoodie.', '["images/h30-1.jpg","images/h30-2.jpg","images/h30-3.jpg","images/h30-4.jpg","images/h30-5.jpg"]', '["L"]', 'L', '46"', '23.5"', '10/10', 'AVAILABLE', '2026-09-08T17:54:39.877Z', '2026-09-08T17:54:39.877Z');
